 <div class="kt-card"><div class="kt-card-header block py-4 min-h-0" data-panel-motion="tools"><div class="canaco-directory-heading"><h3 class="font-semibold text-foreground">Sucursales registradas</h3><p class="text-sm text-muted-foreground">Nombre opcional; ciudad, domicilio, teléfono y ubicación de Google Maps requeridos.</p></div><form method="get" action="<?= e(base_url('sucursales')) ?>" class="canaco-filter-row" role="search"><label class="kt-input canaco-filter-search"><i class="ki-filled ki-magnifier"></i><input type="search" name="q" value="<?= e($f['q']) ?>" placeholder="Sucursal, afiliado o domicilio" aria-label="Buscar sucursales"></label><select class="kt-select" name="afiliado" aria-label="Filtrar por afiliado"><option value="0">Todos los afiliados</option><?php foreach($afiliados as $a): ?><option value="<?= (int)$a['idAfiliado'] ?>" <?= $f['afiliado']==(int)$a['idAfiliado']?'selected':'' ?>><?= e($a['nombre_comercial']) ?></option><?php endforeach; ?></select><select class="kt-select" name="estado" aria-label="Filtrar por estado"><option value="">Todos los estados</option><option value="1" <?= $f['estado']==='1'?'selected':'' ?>>Activas</option><option value="0" <?= $f['estado']==='0'?'selected':'' ?>>Inactivas</option></select><button class="kt-btn kt-btn-light" type="submit">Filtrar</button><button type="button" id="btnNuevaSucursal" class="kt-btn kt-btn-primary"><i class="ki-filled ki-plus"></i>Registrar sucursal</button></form></div>
